                /**
                * Vytvoreni gridu s prikazy po kontrole
                */
                createGridFazeKontrola(tabPrikazy) {
                    const that = this;
                    that.$gridPrikazyFazeKontrola = $.newDiv().gautofit({ resizersOnTab: false })
                        .appendTo(tabPrikazy)
                        .ggrid({
                        name: "gridPrikazy",
                        columnMode: "full",
                        rowsChecked: "tpep_check",
                        multi: true,
                        //multiMenu: pozastavitPrikazy.createBar(["actPozastavit"]),
                        multiMenu: [
                            WebClient.BucWizard.createItemForMultiMenu("actSuccessRecords", "Vybrat vyhovující", () => that.$gridPrikazyFazeKontrola, 200, true),
                            WebClient.BucWizard.createItemForMultiMenu("actRemoveSuccessRecords", "Zrušit vyhovující", () => that.$gridPrikazyFazeKontrola, 200, false),
                            WebClient.BucWizard.createItemForMultiMenu("actWarningRecords", "Vybrat upozornění", () => that.$gridPrikazyFazeKontrola, 206, true),
                            WebClient.BucWizard.createItemForMultiMenu("actRemoveWarningRecords", "Zrušit upozornění", () => that.$gridPrikazyFazeKontrola, 206, false),
                            WebClient.BucWizard.createItemForMultiMenu("actUnSuccessRecords", "Vybrat nevyhovující", () => that.$gridPrikazyFazeKontrola, 400, true),
                            WebClient.BucWizard.createItemForMultiMenu("actRemoveUnSuccessRecords", "Zrušit nevyhovující", () => that.$gridPrikazyFazeKontrola, 400, false)
                        ],
                        columns: WebClient.BucGrid.Prikaz.createGridFormat(that, true),
                        defaultProfile: WebClient.BucGrid.Prikaz.getGridProfilesPrikaz(true)[0],
                        profiles: WebClient.BucGrid.Prikaz.getGridProfilesPrikaz(true),
                        selection: function (ev, info) {
                            var finalCounter = 0.00;
                            var finalCounterText = "0";
                            var data = info.getSelection();
                            for (var i = 0; i < data.length; i++) {
                                var number_c = data[i].c?.toString();
                                var errKod = data[i].err_kod;
                                if (errKod != null && errKod != undefined) {
                                    if (data[i].tpep_check && number_c != undefined && (errKod == 0 || errKod > 50)) { //if (data[i].tpep_kind == 206 || data[i].tpep_kind == 200 && data[i].c != undefined)
                                        finalCounter = finalCounter + parseFloat(number_c);
                                        var finalCounterText = parseFloat(finalCounter.toString()).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
                                    }
                                }
                            }
                            if (finalCounter == 0) {
                                //viewKpi[0].primaryText = "Připraveno: 0";
                                that.flashPanelPocet.gflashpanel("option", "content", "Připraveno příkazů: 0, částka celkem: 0");
                            }
                            else if (that.faze1pocetVyhovujicich == 1) {
                                that.prikazyFlashPanelPocet = (info.view.getDataRows() != undefined ? info.view.getDataRows().length : 0);
                                that.prikazyFlashPanelCastkaCelkem = finalCounterText.replace(".", ",");
                                //viewKpi[0].primaryText = "Připraveno: " + info.getSelection().length;
                                that.flashPanelPocet.gflashpanel("option", "content", "Připraveno příkazů: " + info.view.getDataRows().length + ", částka celkem: " + finalCounterText.replace(".", ",") + "");
                                that.faze1pocetVyhovujicich++;
                            }
                            else {
                                //viewKpi[0].primaryText = "Připraveno: " + info.getSelection().length;
                                that.flashPanelPocet.gflashpanel("option", "content", "Připraveno příkazů: " + (info.view.getDataRows().length != undefined ? info.view.getDataRows().length : 0) + ", částka celkem: " + finalCounterText.replace(".", ",") + "");
                            }
                        },
                        defaultAction: new GAction({
                            name: "doubleClickGridPrikazyKontrola",
                            run: (ev, ctx) => {
                                that.detail(that.$gridPrikazyFazeKontrola);
                            }
                        }),
                    });
                }
