                                that.prikazyFlashPanelCastkaCelkem = finalCounterText.replace(".", ",");
                                that.flashPanelPocet.gflashpanel("option", "content", "Připraveno příkazů: " + (data.length != undefined ? data.length : 0) + ", částka celkem: " + finalCounterText.replace(".", ",") + "");
                                that.faze1pocetVyhovujicich++;
