                /**
                 * Naplnění gridu seznamu prikazu
                 *
                 * @param {JQuery} $grid grid
                 */
                fillSeznamPrikazu($grid, stepWizzard) {
                    let that = this;
                    let defClose = $.Deferred();
                    // filtry
                    let filters = { tpep_ano: 1, ikc: that.ikc };
                    ;
                    let returnObj = {
                        data: null
                    };
                    // deferred objekt pro zřetězení otázek (deferred = odlozeny)
                    let def = $.Deferred().resolve(returnObj).promise();
                    // obsluha jednotlivých fází
                    this.beginOperation("Načítám data");
                    $grid.gcover({ text: "Probíhá načítání vybraných příkazů" });
                    def.then(function (returnObj) {
                        that.isl.Prikaz.list({ filters })
                            .get()
                            .then(function (ret) {
                            (ret.data.length == 0 ? that.jsouPrikazyDostupne = false : that.jsouPrikazyDostupne = true);
                            if (ret.data.length == 0) {
                                that.prikazyFlashPanelPocet = 0; //(info.view.getDataRows().length != undefined ? info.view.getDataRows().length : 0);
                                that.prikazyFlashPanelCastkaCelkem = "0"; //finalCounterText.replace(".", ",");
                                that.flashPanelPocet.gflashpanel({ state: "info", content: "Připraveno příkazů: " + that.prikazyFlashPanelPocet + ", částka celkem: " + that.prikazyFlashPanelCastkaCelkem + "", disabled: true });
                            }
                            that.pripustneBanky = [];
                            for (var i = 0; i < ret.data.length; i++) {
                                var sk_vl = ret.data[i].sk_vl;
                                if (sk_vl) {
                                    that.pripustneBanky.push(sk_vl);
                                }
                            }
                            var bankaFirst = that.pripustneBanky[0];
                            that.element.findForms().findFields("nazev_sbu").gfield("option", "serverFilters", { sk_vl: that.pripustneBanky }).gfield("setInitial", bankaFirst);
                            def = $.Deferred();
                            let view = new Gordic.Data.View(ret.data);
                            //that.faze1Counter(view);
                            // nastavení dat a překreslení gridu
                            let dat = view.getDataRows(!true, "data") || [];
                            for (var i = 0; i < dat.length; i++) {
                                var errCode = dat[i].err_kod;
                                //if (!dat[i].tpep_check && errCode != null && errCode <= 50) {
                                //    dat[i].tpep_check = false;
                                //}
                                if (!dat[i].tpep_check && errCode != null && errCode >= 51 && errCode <= 99) {
                                    dat[i].tpep_check = true;
                                }
                                if (!dat[i].tpep_check && errCode != null && errCode == 0) {
                                    dat[i].tpep_check = true;
                                }
                            }
                            view.updateData(dat);
                            $grid.ggrid("setData", view);
                            if (that.kpiPanel != undefined && stepWizzard == 1) {
                                WebClient.BucWizard.refreshKPIPanel(that.kpiPanel, ret.data);
                            }
                            $grid.gcover("destroy");
                            if (stepWizzard == 3) {
                                that.generujDavku();
                                that.beginOperation("Probíhá generování dávky");
                            }
                            //that.endOperation();
                            return def.promise();
                        })
                            .fail(function (xhr, type, vobj) {
                            // operace nedopadla
                            def.reject(xhr, type, vobj);
                        });
                        let def = $.Deferred();
                        //let view = new Gordic.Data.View(that.vybraneRadky);
                        //// nastavení dat a překreslení gridu
                        //$grid.ggrid("setData", view);
                        that.endOperation();
                        return def.promise();
                    }).done(function () {
                    })
                        .always(function () {
                        that.endOperation();
                    });
                    //that.endOperation();
                    return defClose.promise();
                }
