                /**
                 * Kopirovani davky prikazu do lokalniho uloziste
                 */
                kopirovatDavku() {
                    const that = this;
                    that.bankaPodpisDto.banka = that.dataBankaDto;
                    if (that.bankaParametryDavky.Permissions.LzeOdeslat.value) {
                        //Confirm dialog pro potvrzení nakopírování vygenerované dávky do uložiště pro komunikaci s bankou.
                        that.dialogs.confirm("Kopírování dávky příkazů", "Přejete si vygenerovaný soubor s příkazy do banky nakopírovat do adresáře: " + that.bankaPodpisDto.vys_pth).on("close", (ev, obj) => {
                            if (obj === "yes") {
                                //Odeslání platebních příkazů ( dávky ) do banky - dávka nebude nakopírována do adresáře
                                //that.bankaPodpisDto.Permissions.LzeOdeslat = true;
                                //that.bankaParametryDavky.permissions = ;
                                that.beginOperation("Kopíruji soubor/y");
                                //Todo: metoda odesliPrikazy musí mít na vstupu GDavkaPDBDto - 
                                that.bankaPodpisDto.Permissions = that.bankaParametryDavky.Permissions;
                                if (that.bankaParametryDavky.registrDavekPrikazu.soubor != undefined) {
                                    that.bankaPodpisDto.registrDavekPrikazu.soubor = that.bankaParametryDavky.registrDavekPrikazu.soubor;
                                }
                                if (that.bankaPodpisDto.banka.registrDavekPrikazu != undefined) {
                                    that.bankaPodpisDto.banka.registrDavekPrikazu.ixb_ele_dav = that.ixb_ele;
                                    that.bankaPodpisDto.ixp_dav = that.ixp_ele;
                                    that.bankaPodpisDto.banka.ixp = that.ixp_ele;
                                    that.bankaPodpisDto.banka.registrDavekPrikazu.ixp_dav = that.ixp_ele;
                                }
                                that.isl.Prikaz.odesliPrikazy({ data: /*that.bankaParametryDavky*/ that.bankaPodpisDto /*that.vstupniDataDto*/ }).get().then(function (data) {
                                    that.endOperation();
                                    that.notification("add", { icon: "fa-check-circle g-state-text g-state-success", id: "CopyDavka", state: "success", title: "", content: "Soubor dávky " + that.bankaPodpisDto.registrDavekPrikazu.soubor + " byl nakopírován do adresáře " + that.bankaPodpisDto.vys_pth }); //RC 33112043 :  byl stažen
                                    return data;
                                }).fail(function () {
                                    that.endOperation();
                                });
                            }
                            else {
                                //Neodeslání platebních příkazů ( dávky ) do banky - dávka nebude nakopírována do adresáře, nebude odesílána WS
                                that.beginOperation("Dokončení operace");
                                that.isl.Prikaz.neodesilejPrikazy({ data: that.bankaPodpisDto }).get().then(function (data) {
                                    that.endOperation();
                                    that.notification("add", { icon: "fa-check-circle g-state-text g-state-success", id: "CopyDavkaErr", state: "success", title: "", content: data.result.errors[0].message?.toString() });
                                    return data;
                                }).fail(function () {
                                    that.endOperation();
                                });
                            }
                        });
                    }
                    else {
                        that.bankaPodpisDto.Permissions = that.bankaParametryDavky.Permissions;
                        that.isl.Prikaz.odesliPrikazy({ data: /*that.bankaParametryDavky*/ that.bankaPodpisDto }).get().then(function (data) {
                            that.endOperation();
                            if (data.result.errors != undefined) {
                                that.dialogs.messageBox("Odesílání dávky", data.result.errors[0].message?.toString(), undefined, "fa-info-circle g-state-text g-state-info", 350) //RC 24100119 : Na některých pohybech jsou ručně pořízené zápisy. Chcete zachovat zápisy těchto pohybů?
                                    .on("yes", function () {
                                    return;
                                })
                                    .on("close", function () {
                                    return;
                                });
                            }
                            else {
                                that.notification("add", { icon: "fa-check-circle g-state-text g-state-success", id: "CopyDavka", state: "success", title: "", content: "Soubor dávky " + that.bankaPodpisDto.registrDavekPrikazu.soubor + " byl nakopírován do adresáře " + that.bankaPodpisDto.vys_pth }); //RC 33112043 :  byl stažen
                            }
                            return data;
                        }).fail(function () {
                            that.endOperation();
                        });
                    }
                }
